// IsZero reports whether no resource map is set.
func (r *Resources) IsZero() bool {
	return r.Alerts == nil &&
		r.Apps == nil &&
		r.Catalogs == nil &&
		r.ClusterPolicies == nil &&
		r.Clusters == nil &&
		r.Dashboards == nil &&
		r.DatabaseCatalogs == nil &&
		r.DatabaseInstances == nil &&
		r.Experiments == nil &&
		r.ExternalLocations == nil &&
		r.GenieSpaces == nil &&
		r.InstancePools == nil &&
		r.Snapshots == nil &&
		r.JobRuns == nil &&
		r.Jobs == nil &&
		r.McpServices == nil &&
		r.ModelProviderServices == nil &&
		r.ModelServices == nil &&
		r.ModelServingEndpoints == nil &&
		r.Models == nil &&
		r.Pipelines == nil &&
		r.PostgresBranches == nil &&
		r.PostgresCatalogs == nil &&
		r.PostgresDatabases == nil &&
		r.PostgresEndpoints == nil &&
		r.PostgresProjects == nil &&
		r.PostgresRoles == nil &&
		r.PostgresSnapshotSchedules == nil &&
		r.PostgresSyncedTables == nil &&
		r.QualityMonitors == nil &&
		r.RegisteredModels == nil &&
		r.Schemas == nil &&
		r.SecretScopes == nil &&
		r.Secrets == nil &&
		r.SqlWarehouses == nil &&
		r.SyncedDatabaseTables == nil &&
		r.VectorSearchEndpoints == nil &&
		r.VectorSearchIndexes == nil &&
		r.Volumes == nil
}

// IterateAllGrants calls fn for the grants of every resource that can have them, in
// the order of IterateAllResources, until fn returns false.
func (r *Resources) IterateAllGrants(fn func(typ, name string, grants *[]catalog.PrivilegeAssignment) bool) {
	for _, name := range sortedKeys(r.Catalogs) {
		if x := r.Catalogs[name]; x != nil && !fn("catalogs", name, &x.Grants) {
			return
		}
	}
	for _, name := range sortedKeys(r.ExternalLocations) {
		if x := r.ExternalLocations[name]; x != nil && !fn("external_locations", name, &x.Grants) {
			return
		}
	}
	for _, name := range sortedKeys(r.McpServices) {
		if x := r.McpServices[name]; x != nil && !fn("mcp_services", name, &x.Grants) {
			return
		}
	}
	for _, name := range sortedKeys(r.ModelProviderServices) {
		if x := r.ModelProviderServices[name]; x != nil && !fn("model_provider_services", name, &x.Grants) {
			return
		}
	}
	for _, name := range sortedKeys(r.ModelServices) {
		if x := r.ModelServices[name]; x != nil && !fn("model_services", name, &x.Grants) {
			return
		}
	}
	for _, name := range sortedKeys(r.RegisteredModels) {
		if x := r.RegisteredModels[name]; x != nil && !fn("registered_models", name, &x.Grants) {
			return
		}
	}
	for _, name := range sortedKeys(r.Schemas) {
		if x := r.Schemas[name]; x != nil && !fn("schemas", name, &x.Grants) {
			return
		}
	}
	for _, name := range sortedKeys(r.Secrets) {
		if x := r.Secrets[name]; x != nil && !fn("secrets", name, &x.Grants) {
			return
		}
	}
	for _, name := range sortedKeys(r.VectorSearchIndexes) {
		if x := r.VectorSearchIndexes[name]; x != nil && !fn("vector_search_indexes", name, &x.Grants) {
			return
		}
	}
	for _, name := range sortedKeys(r.Volumes) {
		if x := r.Volumes[name]; x != nil && !fn("volumes", name, &x.Grants) {
			return
		}
	}
}
